import { useEffect, useState } from "react";
function Products(props) {
    // console.log(data["data"][0]);
    let i = 1;
    return props.data.map((element)=><>
        <h2 className="card-header">Товарчик намбер {i++}!</h2>
        {element.title} <br />
        {element.category} <br />
        {element.price}
        </>)
}

export default Products;
